// Public orientation with fixed choices only. Never accepts claim documents or account details.
export const LEGAL_HELP='https://nalsa.gov.in/faqs/';
const button=(action,value,label)=>`<button type="button" class="secondary" data-entry-action="${action}" data-entry-value="${value}">${label}</button>`;
const routes={bank:['Bank deposit','A savings account, fixed deposit or recurring deposit at a bank.','the bank’s deceased-account claims team'],demat:['Demat account','A statement showing shares held in a demat account.','the depository participant (DP) that services the demat account'],mf:['Mutual-fund folio','A mutual-fund statement showing a folio number; confirm it is not held in demat.','the mutual-fund company (AMC) or its record-service provider (RTA)'],unknown:['I do not know','You do not need to guess.','the institution named on the available statement or passbook']};
export function createJourneyEntry(){
 let mode='start',stage=0,kind='',age='';
 function reset(){mode='start';stage=0;kind='';age='';}
 function startClaim(){reset();mode='claim';}
 function handle(target){const el=target?.closest?.('[data-entry-action]');if(!el)return false;const {entryAction:action,entryValue:value}=el.dataset;
  if(action==='start'){reset();return true;}
  if(action==='claim'){startClaim();return true;}
  if(action==='living'){mode='living';stage=0;return true;}
  if(action==='kind'&&mode==='living'&&value==='paper-shares')return 'old-shares';
  if(action==='kind'&&Object.hasOwn(routes,value)){kind=value;stage=1;return mode==='living'&&value!=='unknown'?'setup-'+value:true;}
  if(action==='age'&&mode==='claim'&&stage===1&&['adult','minor','unsure'].includes(value)){age=value;stage=2;return true;}
  if(action==='back'){if(stage>0){stage--;if(stage===0){kind='';age='';}}else reset();return true;}
  if(action==='continue'&&mode==='living'&&stage===1&&kind!=='unknown'&&Object.hasOwn(routes,kind))return 'setup-'+kind;
  return false;
 }
 function render(t=key=>key){
  const text=key=>t(key).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const p=key=>`<p data-speak>${text(key)}</p>`,h=key=>`<h1 data-speak>${text(key)}</h1>`,more=body=>`<details><summary data-speak>${text('plainMoreDetails')}</summary><div class="detail-body">${body}</div></details>`;
  let body='';
  if(mode==='start')body=h('plainEntryStart')+`<div class="coach-options">${button('living','',text('plainEntryLiving'))}${button('claim','',text('plainEntryDeceased'))}</div>`;
  else if(stage===0)body=h('plainEntryQuestion')+p('plainEntryHelp')+(mode==='claim'?'<p>You do not add a new nominee for a holder who has died. Start by identifying who holds the account.</p>':'')+`<div class="entry-choices">${[['bank','plainPaperBank'],['demat','plainPaperDemat'],['mf','plainPaperMF'],...(mode==='living'?[['paper-shares','oldSharesKind']]:[]),['unknown','unknown']].map(([id,key])=>`<div>${button('kind',id,text(key))}</div>`).join('')}</div><details><summary data-speak>${text('plainWords')}</summary>${p('plainDematMeaning')}${p('plainFolioMeaning')}</details>`;
  else if(mode==='living')body=kind==='unknown'?`<h1>You can begin without knowing the account type</h1><p>Use the name on the passbook or statement to contact the institution through its official website or branch. Keep the document with you; do not upload it here.</p><blockquote>“What kind of account is this, who services it, and where can I check its nomination?”</blockquote>${more('<p>If you have no document, ask the institution you already deal with how to identify the account safely. Do not pay an unknown person to search for it.</p>')}`:h('plainAccountSetup')+p('plainEntryHelp')+button('continue','',text('plainEntryGo'))+more(`<p>${routes[kind][1]}</p><p>You will choose the institution and check what is already recorded. If you cannot use its website, the guided preparation includes a branch or service-centre route.</p>`);
  else if(stage===1)body=`<h1>Would you like help as a child or an adult?</h1><p>This changes the assistance shown, not who is entitled to money. You do not need to give your age or date of birth.</p><div class="coach-options">${button('age','minor','I am under 18')}${button('age','adult','I am an adult')}${button('age','unsure','I am unsure or prefer not to say')}</div>`;
  else body=h('plainClaimNext')+p('plainClaimTeam')+`<h2 data-speak>${text('plainQuestion')}</h2><blockquote data-speak>${text('plainClaimAsk')}</blockquote>`+p('plainClaimWritten')+p('plainClaimReceipt')+p('plainPrivacy')+more(`<h1>Your next step: ask for the claim process</h1><p>Contact ${routes[kind][2]}. ${kind==='unknown'?'Ask it to identify the account and the team that handles claims first.':'Ask for its current process for a deceased holder; do not use a new-nomination form.'}</p>${kind==='mf'?'<p>If the fund units are held in demat, ask the demat service provider instead of using a folio claim process.</p>':''}<blockquote>“I need help with an account after the holder’s death. Which claim route applies, what documents are required for my situation, and how do I get a dated acknowledgement?”</blockquote><p>Ask for a written checklist before travelling or paying for documents. Keep any response privately and ask what is missing if the request cannot proceed.</p>${age!=='adult'?'<p>If it is safe, ask a trusted adult to help you speak to the institution. Ask the institution who may legally act for a minor. A helper is not automatically authorised to sign or receive money for you.</p>':''}<details><summary>${age!=='adult'?'No safe adult to help, or worried about your rights?':'A disagreement or uncertainty about your rights?'}</summary><p>You can seek independent legal-aid guidance from NALSA on <a href="tel:15100">15100</a> or your District Legal Services Authority. Ask what assistance is available for your situation. This is a legal-aid route, not a bank claim service or an emergency line; Virasat cannot promise representation or an outcome.</p><a href="${LEGAL_HELP}" target="_blank" rel="noopener noreferrer">NALSA: legal-aid questions and assistance</a></details><p class="help">Being a child, relative or nominee does not let this website decide inheritance or entitlement. A receipt is not claim approval. Never give a helper your password, PIN or OTP.</p>`);
  return `<section class="nomination-coach" lang="en"><p class="coach-preview" data-speak>${text('plainNotSent')}</p><div class="coach-content" tabindex="-1">${body}</div>${mode!=='start'?`<div class="coach-navigation">${button('back','','Previous')}${button('start','','Choose another situation')}</div>`:''}${more('<p>Leaving or reloading clears your choices. Keep this tab open when opening official guidance. Claim orientation does not submit a claim or update nomination records.</p>')}</section>`;
 }
 function snapshot(){return {mode,stage,kind,age};}
 function restore(value){reset();if(!value||!['start','living','claim'].includes(value.mode))return;mode=value.mode;stage=[0,1,2].includes(value.stage)?value.stage:0;kind=Object.hasOwn(routes,value.kind)?value.kind:'';age=['adult','minor','unsure'].includes(value.age)?value.age:'';}
 return {render,handle,reset,startClaim,snapshot,restore};
}
